/**
 * Generated by `createservice miniapp.ImportB2BAppService`
 */

const dayjs = require('dayjs')
const got = require('got')
const get = require('lodash/get')
const pick = require('lodash/pick')


const { generateGqlQueries } = require('@open-condo/codegen/generate.gql')
const { GQLError, GQLErrorCode: { BAD_USER_INPUT, INTERNAL_ERROR } } = require('@open-condo/keystone/errors')
const { getByCondition } = require('@open-condo/keystone/schema')
const { GQLCustomSchema } = require('@open-condo/keystone/schema')
const { wrapUploadFile } = require('@open-condo/keystone/upload')

const { getDevicePermissions, getDevicePermissionFieldName } = require('@condo/domains/miniapp/schema/fields/devicePermissions')
const { REMOTE_SYSTEM } = require('@dev-portal-api/domains/common/constants/common')
const { MULTIPLE_FOUND } = require('@dev-portal-api/domains/common/constants/errors')
const { developmentClient, productionClient } = require('@dev-portal-api/domains/common/utils/serverClients')
const access = require('@dev-portal-api/domains/miniapp/access/ImportB2BAppService')
const { B2B_APP_ACCESS_RIGHT_SET_APPROVED_STATUS } = require('@dev-portal-api/domains/miniapp/constants/b2bAppAccessRightSet')
const { APP_NOT_FOUND } = require('@dev-portal-api/domains/miniapp/constants/errors')
const { DEV_ENVIRONMENT, PROD_ENVIRONMENT } = require('@dev-portal-api/domains/miniapp/constants/publishing')
const { B2BApp, B2BAppAccessRight, B2BAppAccessRightSet, B2BAppPublishRequest } = require('@dev-portal-api/domains/miniapp/utils/serverSchema')

const { PERMISSION_FIELDS } = require('./B2BAppAccessRightSet')
const { getEnvironmentalFieldsSelection, getEnvironmentalFieldName } = require('./fields/environmental')

const { PUBLISH_REQUEST_APPROVED_STATUS } = require('../constants/publishing')


const ERRORS = {
    DEV_APP_NOT_FOUND: {
        code: BAD_USER_INPUT,
        type: APP_NOT_FOUND,
        message: 'No app with specified ID found on condo development stand',
    },
    PROD_APP_NOT_FOUND: {
        code: BAD_USER_INPUT,
        type: APP_NOT_FOUND,
        message: 'No app with specified ID found on condo production stand',
    },
    MULTIPLE_FOUND: {
        code: INTERNAL_ERROR,
        type: MULTIPLE_FOUND,
        message: 'Unable to determine the object to update because multiple objects were found for the specified importID and exportId',
        messageForUser: 'api.common.MULTIPLE_FOUND',
    },
}

const ENVIRONMENTAL_FIELDS = [
    { from: 'appUrl', to: 'appUrl' },
    { from: 'oidcClient.id', to: 'oidcClientId' },
    ...getDevicePermissions({ listKey: 'B2BApp' })
        // NOTE: remove "is" Prefix
        .map((permission) => ({ from: getDevicePermissionFieldName(permission), to: getDevicePermissionFieldName(permission).substring(2) })),
]

const CondoB2BAppGQL = generateGqlQueries('B2BApp', `{ id name developer developerUrl shortDescription detailedDescription category contextDefaultStatus logo { publicUrl filename mimetype encoding } ${ENVIRONMENTAL_FIELDS.filter(f => !f.from.includes('.')).map(f => f.from).join(' ')} oidcClient { id importId importRemoteSystem } }`)
const CondoB2BAppAccessRightGQL = generateGqlQueries('B2BAppAccessRight', `{ id user { id } accessRightSet { id ${Object.keys(PERMISSION_FIELDS).join(' ')} } }`)
const CondoB2BAppAccessRightSetGQL = generateGqlQueries('B2BAppAccessRightSet', '{ id }')
const CondoOIDCClientGQL = generateGqlQueries('OidcClient', '{ id }')

async function resolveConflicts ({ args, context }) {
    const {
        data: {
            dv,
            sender,
            to: { app: { id: apiAppId } },
            options: { conflictPolicy },
        },
    } = args
    const developmentAppId = get(args, ['data', 'from', 'developmentApp', 'id'])
    const productionAppId = get(args, ['data', 'from', 'productionApp', 'id'])
    const app = await B2BApp.getOne(context, { id: apiAppId }, `id ${getEnvironmentalFieldsSelection(['exportId'])}`)

    if (!app) return

    const jobs = []

    if (developmentAppId) {
        jobs.push({ apiExportId: app.developmentExportId, condoImportId: developmentAppId, client: developmentClient })
    }
    if (productionAppId) {
        jobs.push({ apiExportId: app.productionExportId, condoImportId: productionAppId, client: productionClient })
    }

    for (const { apiExportId, condoImportId, client } of jobs) {
        const conditions = []
        if (apiExportId && apiExportId !== condoImportId) {
            conditions.push({ id: apiExportId })
        }

        const importCondition = { importId: apiAppId, importRemoteSystem: REMOTE_SYSTEM, id_not: condoImportId }
        if (developmentClient.endpoint === productionClient.endpoint && productionAppId && developmentAppId) {
            importCondition.id_not_in = [productionAppId, developmentAppId]
        }
        conditions.push({ AND: [importCondition] })

        const condoApps = await client.getModels({
            modelGql: CondoB2BAppGQL,
            where: {
                OR: conditions,
            },
        })
        if (!condoApps.length) {
            continue
        }

        if (conflictPolicy === 'panic') {
            throw new GQLError(ERRORS.MULTIPLE_FOUND, context)
        }

        const updateInputs = condoApps.map(app => ({
            id: app.id,
            data: conflictPolicy === 'setNull' ? {
                dv,
                sender,
                importId: null,
                importRemoteSystem: null,
            } : {
                dv,
                sender,
                deletedAt: dayjs().toISOString(),
            },
        }))

        await client.updateModels({
            modelGql: CondoB2BAppGQL,
            updateInputs,
        })
    }

    const apiUpdateInput = {
        dv,
        sender,
    }

    if (app.developmentExportId && developmentAppId && app.developmentExportId !== developmentAppId) {
        apiUpdateInput.developmentExportId = null
    }
    if (app.productionExportId && productionAppId && app.productionExportId !== productionAppId) {
        apiUpdateInput.productionExportId = null
    }

    if (Object.keys(apiUpdateInput).length > 2) {
        await B2BApp.update(context, app.id, apiUpdateInput)
    }
}

async function importAppInfo ({ args, context }) {
    const {
        data: {
            dv,
            sender,
            from,
            to: { app: { id: appId } },
        },
    } = args

    const developmentAppId = get(from, ['developmentApp', 'id'])
    const productionAppId = get(from, ['productionApp', 'id'])

    let devApp, prodApp

    if (developmentAppId) {
        devApp = await developmentClient.updateModel({
            modelGql: CondoB2BAppGQL,
            id: developmentAppId,
            updateInput: {
                dv,
                sender,
                importId: appId,
                importRemoteSystem: REMOTE_SYSTEM,
            },
        })
        if (!devApp) {
            throw new GQLError(ERRORS.DEV_APP_NOT_FOUND, context)
        }
    }

    if (productionAppId) {
        prodApp = await productionClient.updateModel({
            modelGql: CondoB2BAppGQL,
            id: productionAppId,
            updateInput: {
                dv,
                sender,
                importId: appId,
                importRemoteSystem: REMOTE_SYSTEM,
            },
        })
        if (!prodApp) {
            throw new GQLError(ERRORS.PROD_APP_NOT_FOUND, context)
        }
    }

    const sourceApp = prodApp ?? devApp
    const updatePayload = {
        dv,
        sender,
        name: sourceApp.name,
        developer: sourceApp.developer,
        developerUrl: sourceApp.developerUrl,
        shortDescription: sourceApp.shortDescription,
        detailedDescription: sourceApp.detailedDescription,
        category: sourceApp.category,
        contextDefaultStatus: sourceApp.contextDefaultStatus,
    }
    if (sourceApp.logo && sourceApp.logo.publicUrl) {
        const client = prodApp ? productionClient : developmentClient
        const stream = got.stream(sourceApp.logo.publicUrl, {
            headers: { 'Authorization': `Bearer ${client.authToken}` },
        })
        // TODO: migrate to new API
        updatePayload.logo = wrapUploadFile({
            stream: stream,
            filename: sourceApp.logo.filename,
            mimetype: sourceApp.logo.mimetype,
            encoding: sourceApp.logo.encoding,
        })
    }

    const queue = []
    if (prodApp) {
        queue.push({ environment: PROD_ENVIRONMENT, app: prodApp, client: productionClient })
    }
    if (devApp) {
        queue.push({ environment: DEV_ENVIRONMENT, app: devApp, client: developmentClient })
    }

    for (const { environment, app, client } of queue) {
        if (app?.oidcClient?.id && !app.oidcClient?.importId) {
            await client.updateModel({
                modelGql: CondoOIDCClientGQL,
                id: app.oidcClient.id,
                updateInput: {
                    dv,
                    sender,
                    importId: appId,
                    importRemoteSystem: REMOTE_SYSTEM,
                },
            })
        }

        for (const { from, to } of ENVIRONMENTAL_FIELDS) {
            const toFieldName = getEnvironmentalFieldName(environment, to)
            updatePayload[toFieldName] = get(app, from, null)
        }

        const exportField = getEnvironmentalFieldName(environment, 'exportId')
        updatePayload[exportField] = app.id
    }

    return await B2BApp.update(context, appId, updatePayload)
}

async function _importAppAccessRightFromEnvironment ({ condoAppId, args, environment, context }) {
    const { data: { dv, sender, to: { app: { id: appId } } } } = args
    const exportField = `${environment}ExportId`

    const serverClient = environment === PROD_ENVIRONMENT
        ? productionClient
        : developmentClient

    const accessRights = await serverClient.getModels({
        modelGql: CondoB2BAppAccessRightGQL,
        where: { app: { id: condoAppId } },
        first: 1,
    })

    if (!accessRights.length) return

    const condoAccessRight = accessRights[0]
    const condoAccessRightSet = condoAccessRight?.accessRightSet

    // STEP 1. Access rights section
    const existingAccessRight = await getByCondition('B2BAppAccessRight', {
        deletedAt: null,
        app: { id: appId },
        environment,
    })
    if (existingAccessRight) {
        await B2BAppAccessRight.softDelete(context, existingAccessRight.id, 'id', {
            dv,
            sender,
        })
    }

    const newAccessRight = await B2BAppAccessRight.create(context, {
        dv,
        sender,
        condoUserId: condoAccessRight.user.id,
        app: { connect: { id: appId } },
        environment,
        [exportField]: condoAccessRight.id,
    })
    await serverClient.updateModel({
        modelGql: CondoB2BAppAccessRightGQL,
        id: condoAccessRight.id,
        updateInput: {
            dv,
            sender,
            importId: newAccessRight.id,
            importRemoteSystem: REMOTE_SYSTEM,
        },
    })

    // STEP 2. Access rights set section
    if (!condoAccessRightSet) return

    const permissions = pick(condoAccessRightSet, Object.keys(PERMISSION_FIELDS))

    const newRightSet = await B2BAppAccessRightSet.create(context, {
        dv,
        sender,
        app: { connect: { id: appId } },
        status: B2B_APP_ACCESS_RIGHT_SET_APPROVED_STATUS,
        environment,
        [exportField]: condoAccessRight.id,
        ...permissions,
    })
    await serverClient.updateModel({
        modelGql: CondoB2BAppAccessRightSetGQL,
        id: condoAccessRightSet.id,
        updateInput: {
            dv,
            sender,
            importId: newRightSet.id,
            importRemoteSystem: REMOTE_SYSTEM,
        },
    })
}

async function importRightSets ({ args, context }) {
    const developmentAppId = get(args, ['data', 'from', 'developmentApp', 'id'])
    const productionAppId = get(args, ['data', 'from', 'productionApp', 'id'])

    if (developmentAppId) {
        await _importAppAccessRightFromEnvironment({
            condoAppId: developmentAppId,
            environment: DEV_ENVIRONMENT,
            args,
            context,
        })
    }

    if (productionAppId) {
        await _importAppAccessRightFromEnvironment({
            condoAppId: productionAppId,
            environment: PROD_ENVIRONMENT,
            args,
            context,
        })
    }
}

async function allowPublishing ({ args, context }) {
    const {
        data: {
            dv,
            sender,
            from,
            to: { app: { id: appId } },
        },
    } = args
    const productionAppId = get(args, ['data', 'from', 'productionApp', 'id'])
    if (!productionAppId) return

    const publishPayload = {
        dv,
        sender,
        status: PUBLISH_REQUEST_APPROVED_STATUS,
        isAppTested: true,
        isContractSigned: true,
        isInfoApproved: true,
    }

    const existingRequest = await B2BAppPublishRequest.getOne(context, {
        app: { id: appId },
        deletedAt: null,
    }, 'id status')

    if (!existingRequest) {
        await B2BAppPublishRequest.create(context, {
            app: { connect: { id: appId } },
            ...publishPayload,
        })
    } else if (existingRequest.status !== PUBLISH_REQUEST_APPROVED_STATUS) {
        await B2BAppPublishRequest.update(context, existingRequest.id, publishPayload)
    }
}

const ImportB2BAppService = new GQLCustomSchema('ImportB2BAppService', {
    types: [
        {
            access: true,
            type: 'input ImportB2BAppFromInput { developmentApp: B2BAppWhereUniqueInput, productionApp: B2BAppWhereUniqueInput }',
        },
        {
            access: true,
            type: 'input ImportB2BAppToInput { app: B2BAppWhereUniqueInput! }',
        },
        {
            access: true,
            type: 'input ImportB2BAppOptionsInput { conflictPolicy: ImportAppConflictPolicy! }',
        },
        {
            access: true,
            type: 'input ImportB2BAppInput { dv: Int!, sender: SenderFieldInput!, from: ImportB2BAppFromInput!, to: ImportB2BAppToInput!, options: ImportB2BAppOptionsInput! }',
        },
        {
            access: true,
            type: 'type ImportB2BAppOutput { success: Boolean! }',
        },
    ],
    
    mutations: [
        {
            access: access.canImportB2BApp,
            schema: 'importB2BApp(data: ImportB2BAppInput!): ImportB2BAppOutput',
            resolver: async (parent, args, context, info, extra = {}) => {

                // Step 0. Resolve conflicts if necessary (app was already published for some reason)
                await resolveConflicts({ args, context })

                // Step 1. App info sync
                await importAppInfo({ args, context })

                // Step 2. Right sets info
                await importRightSets({ args, context })

                // Step 3. Allow future publishing
                await allowPublishing({ args, context })
                
                return {
                    success: true,
                }
            },
        },
    ],
    
})

module.exports = {
    ImportB2BAppService,
}
